#include "WorkspaceLayouts.h"
static void testWorkspaces(const File& root){
    WorkspaceLayout layout;for(int i=0;i<workspacePaneCount;++i){layout.windows.push_back({220.f+i,100.f+i,800,400,i<4,i==3});layout.order.push_back(i);}layout.active=3;
    auto json=workspaceToJson(layout);WorkspaceLayout loaded;expect(workspaceFromJson(json,loaded).wasOk()&&loaded==layout,"workspace roundtrip preserves all fifteen windows, focus, maximized restores and stacking");
    auto text=JSON::toString(json);expect(workspaceFromJson(JSON::parse(text),loaded).wasOk()&&loaded==layout,"workspace survives actual JSON encoding");
    auto sentinel=loaded;auto corrupt=[&](const var& value){WorkspaceLayout next=sentinel;return workspaceFromJson(value,next).failed()&&next==sentinel;};
    for(const auto& key:{"schema","width","height","browser","browserWidth","windows","order"}){auto bad=JSON::parse(text);bad.getDynamicObject()->removeProperty(key);expect(corrupt(bad),("missing workspace field is rejected atomically: "+String(key)).toRawUTF8());}
    for(auto v:{var("1440"),var(1440.5),var((int64)4294968736LL),var(0),var(32769)}){auto bad=JSON::parse(text);bad.getDynamicObject()->setProperty("width",v);expect(corrupt(bad),"invalid canvas type/range cannot narrow or coerce into a valid size");}
    for(auto v:{var(0),var(1),var("false")}){auto bad=JSON::parse(text);bad.getDynamicObject()->setProperty("browser",v);expect(corrupt(bad),"workspace flags require actual JSON booleans");}
    for(auto v:{var(159),var(341),var("216"),var(std::numeric_limits<double>::infinity())}){auto bad=JSON::parse(text);bad.getDynamicObject()->setProperty("browserWidth",v);expect(corrupt(bad),"invalid Browser width is rejected");}
    for(auto key:{"x","y","w","h"}){auto bad=JSON::parse(text);(*bad["windows"].getArray())[0].getDynamicObject()->setProperty(key,std::numeric_limits<double>::quiet_NaN());expect(corrupt(bad),("nonfinite window geometry is rejected: "+String(key)).toRawUTF8());}
    {auto bad=JSON::parse(text);(*bad["windows"].getArray())[0].getDynamicObject()->setProperty("w",-1);expect(corrupt(bad),"negative window dimensions are rejected");}
    {auto bad=JSON::parse(text);bad["order"].getArray()->set(1,0);expect(corrupt(bad),"duplicate stacking indices are rejected");}
    {auto bad=JSON::parse(text);bad["order"].getArray()->set(1,1.5);expect(corrupt(bad),"fractional stacking indices are rejected");}
    {auto bad=JSON::parse(text);bad.getDynamicObject()->setProperty("active",workspacePaneCount);expect(corrupt(bad),"out-of-range active pane is rejected");}
    {auto legacy=JSON::parse(text);legacy.getDynamicObject()->removeProperty("active");legacy["windows"].getArray()->resize(5);legacy["order"].getArray()->resize(5);expect(workspaceFromJson(legacy,loaded).wasOk()&&loaded.windows.size()==5&&loaded.active==3,"legacy five-window layouts derive focus from the topmost visible pane");}
    auto file=root.getChildFile("workspace-library-checks.json");file.deleteFile();WorkspaceLibrary library;expect(loadWorkspaceLibrary(file,library).wasOk()&&library.empty()&&!file.exists(),"absent workspace library remains absent on read");
    WorkspacePreset p{"user-first",String::fromUTF8("Моя студия"),layout};expect(putWorkspacePreset(file,p,false,workspaceLibraryToken(file)).wasOk(),"Unicode named workspace saves locally");expect(loadWorkspaceLibrary(file,library).wasOk()&&library==WorkspaceLibrary{p},"workspace library roundtrip retains exact contents");auto before=file.loadFileAsString();auto token=workspaceLibraryToken(file);
    expect(putWorkspacePreset(file,p,false,token).failed()&&file.loadFileAsString()==before,"an existing workspace needs explicit update");auto duplicate=p;duplicate.id="user-second";expect(putWorkspacePreset(file,duplicate,false,token).failed()&&file.loadFileAsString()==before,"duplicate workspace name is rejected without mutation");
    duplicate.name="Mixing";expect(putWorkspacePreset(file,duplicate,false,token).wasOk(),"second distinct workspace appends");auto stale=token;token=workspaceLibraryToken(file);before=file.loadFileAsString();p.name="Renamed";expect(putWorkspacePreset(file,p,true,stale).failed()&&removeWorkspacePreset(file,p.id,stale).failed()&&file.loadFileAsString()==before,"stale update and delete cannot overwrite a newer workspace library");
    expect(putWorkspacePreset(file,p,true,token).wasOk(),"explicit rename/update preserves workspace identity");loadWorkspaceLibrary(file,library);expect(library[0].id==p.id&&library[0].name=="Renamed"&&library[0].layout==layout,"workspace rename preserves saved geometry");
    auto exported=root.getChildFile("workspace-test.pulseworkspace");WorkspacePreset imported;expect(saveWorkspacePreset(exported,p).wasOk()&&loadWorkspacePreset(exported,imported).wasOk()&&imported==p,"single workspace export/import preserves layout without project state");
    exported.replaceWithText("{}");auto preserved=imported;expect(loadWorkspacePreset(exported,imported).failed()&&imported==preserved,"invalid import leaves the destination preset intact");
    token=workspaceLibraryToken(file);expect(removeWorkspacePreset(file,p.id,token).wasOk()&&loadWorkspaceLibrary(file,library).wasOk()&&library.size()==1&&library[0].id==duplicate.id,"delete removes only the captured workspace");before=file.loadFileAsString();expect(removeWorkspacePreset(file,p.id,workspaceLibraryToken(file)).failed()&&file.loadFileAsString()==before,"repeated removal cannot delete another entry");
    file.replaceWithText("broken");before=file.loadFileAsString();library={p};expect(loadWorkspaceLibrary(file,library).failed()&&library==WorkspaceLibrary{p}&&putWorkspacePreset(file,p,false,workspaceLibraryToken(file)).failed()&&file.loadFileAsString()==before,"corrupt workspace library cannot be silently replaced");
    WorkspaceLibrary full;for(int i=0;i<maxWorkspacePresets;++i)full.push_back({"user-"+String(i),"Layout "+String(i),layout});expect(validateWorkspaceLibrary(full).wasOk(),"workspace library accepts 32 named layouts");full.push_back({"user-extra","Extra",layout});expect(validateWorkspaceLibrary(full).failed(),"workspace capacity is bounded");
    for(auto name:{String(),String(" spaced "),String("line\nbreak"),String::repeatedString("x",65)}){auto bad=p;bad.name=name;expect(validateWorkspaceLibrary({bad}).failed(),"empty, padded, control and oversized names are rejected");}
    file.replaceWithText(String::repeatedString("x",(int)maxWorkspaceLibraryBytes+1));expect(loadWorkspaceLibrary(file,library).failed(),"oversized workspace library is rejected before parsing");
    auto prefs=root.getChildFile("interface-checks.json");prefs.deleteFile();int scale=175;expect(loadInterfaceScale(prefs,scale).wasOk()&&scale==100&&!prefs.exists(),"absent scale settings use 100 percent without writing");
    for(int value:interfaceScales)expect(saveInterfaceScale(prefs,value).wasOk()&&loadInterfaceScale(prefs,scale).wasOk()&&scale==value,("every interface scale roundtrips: "+String(value)).toRawUTF8());
    before=prefs.loadFileAsString();expect(saveInterfaceScale(prefs,0).failed()&&saveInterfaceScale(prefs,201).failed()&&prefs.loadFileAsString()==before,"invalid scale cannot overwrite a valid preference");prefs.replaceWithText("broken");scale=100;expect(loadInterfaceScale(prefs,scale).failed()&&scale==100&&saveInterfaceScale(prefs,125).failed()&&prefs.loadFileAsString()=="broken","corrupt scale preference remains intact on load and explicit change");
}
